    },
    {
      "id": "R4",
      "summary_ko": "사람이 말 옆이 아니라 앞에서 걸어가고 있음."
    }
  ],
  "candidates": [
    {
      "id": "C1",
      "summary_ko": "기수가 없는데도 말의 옆구리에 유령 다리와 등자 구조물이 떠 있음."
    }
  ],
  "pairs": [
    {
      "reference_id": "R1",
